   check('guided-attain-limit',0,'a_n=[1+(-1)ⁿ]/(2n)。哪个依据支持它趋于 0？',['奇数项取到 0，所以不能收敛','0≤a_n≤1/n，所有尾项可共同控制','数列有界就一定收敛'],1,'奇数项为 0，偶数项为 1/n；两类项都能放入同一个逐渐收紧的误差要求中。'),
   check('guided-majorant',1,'误差为 1/(n+1)²，为什么能改为检查 1/n²<ε？',['因为两式恒等','因为 1/(n+1)²<1/n²，控制上界就能控制原误差','因为分母越大，分式越大'],1,'n≥1 时两分母为正，(n+1)²>n²；减小正分母得到较大的上界，这是充分条件。'),
   check('guided-no-moving-N',1,'给定 ε 后选定 N，正式证明接下来必须检查什么？',['只检查 n=N+1','对每个 n>N，使用同一个 N 验证误差','让 N 随每个正在检查的 n 改动'],1,'定义中的一个门槛同时管住全部尾项；不能让门槛跟着被检验对象移动。'),
